class FIFOModel:
    def __init__(self, capacity):
        self.capacity = capacity
        self._items = []

    def enqueue(self, value):
        if self.is_full():
            return False
        self._items.append(value)
        return True

    def dequeue(self):
        if self.is_empty():
            return None
        return self._items.pop(0)

    def is_empty(self):
        return len(self._items) == 0

    def is_full(self):
        return len(self._items) >= self.capacity

